<td>{{ $m['last'] ? '৳'.number_format($m['last'],2) : '—' }}</td><td>{{ $m['avg'] ? '৳'.number_format($m['avg'],2) : '—' }}</td><td style="background:#FFFBEB"><b>{{ $m['fifo'] ? '৳'.number_format($m['fifo'],2) : '—' }}</b></td><td>{{ $m['fifo'] ? '15%' : '—' }}</td><td>{{ $m['min'] ? '৳'.number_format($m['min'],2) : '—' }}</td><td>{{ $m['profit'] !== null ? '৳'.number_format($m['profit'],2) : '—' }}</td><td>{{ $m['pct'] !== null ? number_format($m['pct'],1).'%' : '—' }}</td><td style="color:{{ $m['bcol'] }};white-space:nowrap">{{ $m['bundle'] }}</td><td style="color:{{ $m['col'] }};font-weight:700;white-space:nowrap">{{ $m['state'] }}</td>